"""Generate the release landing page from the tested offline BEA demo."""
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
HERO = '''<nav class="topnav" aria-label="Main navigation"><a class="brand" href="#home"><span class="mark">OD</span> Open Decision Core</a><div><a href="#ecosystem">Architecture</a><a href="#demo">Demo</a><a href="https://github.com/Shaulska/open-decision-core">GitHub ↗</a></div></nav>
<section class="hero" id="home"><div class="hero-copy"><div class="eyebrow">OPEN-SOURCE MVP · v0.3.0</div><h1>Could you have<br>known it <em>then?</em></h1><p>Audit the evidence behind AI and ML decisions before trusting their results. Exact data versions, explicit cutoffs and reproducible audit receipts.</p><div class="actions"><a class="primary" href="#demo">Explore the replay ↓</a><a class="secondary" href="https://github.com/Shaulska/open-decision-core">View source ↗</a></div><small>Apache-2.0 · Python · Local-first · No API keys</small></div><div class="hero-visual"><div class="eyebrow">EVIDENCE TIMELINE / BEA 2024 Q1</div><div class="timeline-row"><div><b>Apr 25</b><small>Advance estimate</small></div><strong>1.6%</strong><span class="tag ok">AVAILABLE</span></div><div class="cutoff">APR 26 · DECISION CUTOFF</div><div class="timeline-row"><div><b>May 30</b><small>Second estimate</small></div><strong>1.3%</strong><span class="tag bad">FUTURE</span></div><div class="timeline-row"><div><b>Jun 27</b><small>Third estimate</small></div><strong>1.4%</strong><span class="tag bad">FUTURE</span></div><p class="tiny">Actual release values; illustrative cutoff. Provider publication metadata, not local receipt.</p></div></section>
<section id="ecosystem" class="ecosystem"><div class="eyebrow">THE ECOSYSTEM</div><h2>One evidence contract. Three layers.</h2><div class="modules"><article><span class="stage">01 / IMPLEMENTED</span><h3>Temporal Audit</h3><p>Audit declared availability, version references and lineage. Replay evidence at a decision cutoff.</p></article><article><span class="stage planned">02 / ROADMAP</span><h3>Decision Policy</h3><p>Evaluate risk, abstention and when human review is needed. Not yet implemented.</p></article><article><span class="stage planned">03 / ROADMAP</span><h3>Research Lab</h3><p>Compare prediction and decision policies against independent outcomes. Planned.</p></article></div></section>
<section class="developers"><div><div class="eyebrow">FOR DEVELOPERS</div><h2>Integrate the audit, not another model.</h2><p>Run from a cloned repository with Python 3.10+. A receipt contains the verdict, findings and deterministic hashes. It is not a signature or permission to act.</p><a href="https://github.com/Shaulska/open-decision-core/blob/main/docs/CONTRACT.md">Read the evidence contract ↗</a></div><pre><code>python -m odc audit examples/timely.json\npython -m odc audit examples/future-revision.json\npython -m odc verify examples/demo.json \\\n  examples/demo.receipt.json</code></pre></section>'''
CSS = '''
main{max-width:1160px;padding-top:20px} .topnav{display:flex;align-items:center;justify-content:space-between;gap:12px;border-bottom:1px solid var(--line);padding:10px 0 19px}.topnav div{display:flex;gap:18px;flex-wrap:wrap}.topnav a{text-decoration:none;font-weight:650;font-size:13px}.brand{display:flex;align-items:center;gap:9px;color:var(--navy)}.mark{display:grid;place-items:center;background:var(--blue);color:white;width:34px;height:34px;border-radius:7px;font-weight:800;letter-spacing:-.04em}.hero{display:grid;grid-template-columns:1.1fr .9fr;gap:36px;align-items:center;margin:38px 0 28px;padding:32px 0}.hero h1{font-size:clamp(38px,6vw,70px);color:var(--navy);margin:16px 0;line-height:1.02;letter-spacing:-.06em}.hero h1 em{font-style:normal;color:var(--blue)}.hero-copy>p{font-size:18px;max-width:540px;color:var(--muted)}.actions{display:flex;gap:10px;flex-wrap:wrap;margin:26px 0 18px}.actions a{font-weight:650;text-decoration:none;padding:11px 16px;border-radius:7px}.primary{background:var(--blue);color:white}.secondary{border:1px solid #a9bac8;background:white}.hero-visual{background:white;border:1px solid var(--line);border-radius:16px;padding:23px;box-shadow:0 15px 40px #12304a0b}.timeline-row{display:grid;grid-template-columns:1fr auto auto;align-items:center;gap:10px;padding:17px 0;border-bottom:1px solid var(--line)}.timeline-row small{display:block}.timeline-row strong{font-size:22px;letter-spacing:-.04em}.tag{font-size:9px;font-weight:750;letter-spacing:.04em;padding:4px 6px;border-radius:4px}.ok{background:#e7f4ed;color:#086346}.bad{background:#fbe9e9;color:#9b2630}.cutoff{font-size:10px;letter-spacing:.08em;color:var(--blue);font-weight:700;padding:10px 0 0;border-top:2px solid var(--blue);margin-top:5px}.tiny{font-size:12px;color:var(--muted)}.ecosystem{padding:25px 0}.ecosystem h2,.developers h2{font-size:clamp(22px,3vw,32px);letter-spacing:-.035em;margin-top:7px}.modules{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.modules article{background:white;border:1px solid var(--line);border-radius:12px;padding:20px}.modules article:first-child{border-top:4px solid var(--blue)}.modules h3{font-size:20px;margin:12px 0 5px}.modules p{color:var(--muted)}.stage{font-size:10px;font-weight:750;color:var(--blue);letter-spacing:.1em}.planned{color:var(--muted)}.developers{display:grid;grid-template-columns:1fr 1fr;gap:20px;align-items:center;padding:22px 0 35px}.developers pre{background:#12283b;color:#dbe9f8;margin:0;padding:20px}.demo-heading{padding-top:24px;border-top:1px solid var(--line)}.demo-heading h1{font-size:32px}.topnav a:focus-visible,.actions a:focus-visible{outline:3px solid #76a9df;outline-offset:3px}@media(max-width:760px){.hero,.developers{grid-template-columns:1fr;gap:18px}.hero{margin:20px 0;padding:12px 0}.modules{grid-template-columns:1fr}.topnav{align-items:flex-start;flex-direction:column}.topnav div{gap:12px}.hero-visual{padding:16px}.timeline-row{gap:6px}.hero h1 br{display:none}}
'''

def build():
    demo = (ROOT / 'examples/bea/index.html').read_text(encoding='utf-8')
    page = demo.replace('<title>Open Decision Core | Evidence replay</title>', '<title>Open Decision Core — Temporal evidence audit</title><meta name="description" content="A local-first toolkit for auditing exact data versions and evidence availability at decision time.">', 1)
    page = page.replace('</style>', CSS + '</style>', 1)
    page = page.replace('<main>\n<header>', '<main>\n' + HERO + '\n<header id="demo" class="demo-heading">', 1)
    page = page.replace('OPEN DECISION CORE / MVP 0.3', 'INTERACTIVE REPLAY / v0.3.0', 1).replace('<h1>Could you have known it then?</h1>', '<h1>Replay a real data revision.</h1>', 1)
    return page

if __name__ == '__main__':
    (ROOT / 'site/index.html').write_text(build(), encoding='utf-8')
